-- Tuner v3.6
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer
if not LocalPlayer then
	warn("[Tuner] No LocalPlayer — run as LocalScript/Executor")
	return
end
local pg = LocalPlayer:FindFirstChild("PlayerGui")
if not pg then
    -- Wait briefly, don't hard fail
	pg = LocalPlayer:WaitForChild("PlayerGui", 5)
	if not pg then
		warn("[Tuner] PlayerGui not found");
		return
	end
end
-- Safe remove old UI — no error if none exists
local old = pg:FindFirstChild("CarTunerUI")
if old then
	pcall(function()
		old:Destroy()
	end)
end
local HttpService = game:GetService("HttpService")

-- ===== _G GLOBAL STORE =====
_G.TunerStored = _G.TunerStored or _G["***"] or nil
if not _G.TunerStored then
	local j = workspace:GetAttribute("***")
	if j and type(j) == "string" and # j > 4 then
		local ok, t = pcall(HttpService.JSONDecode, HttpService, j)
		if ok and type(t) == "table" then
			_G.TunerStored = t
		end
	end
end
local function saveGlobal(tbl)
	_G.TunerStored = tbl
	_G["***"] = tbl
	local ok, json = pcall(HttpService.JSONEncode, HttpService, tbl)
	if ok then
		pcall(function()
			workspace:SetAttribute("***", json)
		end)
	end
end
local function loadGlobal()
	if _G.TunerStored and type(_G.TunerStored) == "table" and next(_G.TunerStored) ~= nil then
		return _G.TunerStored
	end
	if _G["***"] and type(_G["***"]) == "table" and next(_G["***"]) ~= nil then
		return _G["***"]
	end
	local j = workspace:GetAttribute("***")
	if j and type(j) == "string" and # j > 4 then
		local ok, t = pcall(HttpService.JSONDecode, HttpService, j)
		if ok and type(t) == "table" and next(t) ~= nil then
			_G.TunerStored = t;
			return t
		end
	end
	return nil
end
local function findAllCars()
	local t = {}
	for _, o in ipairs(workspace:GetChildren()) do
		local ok = pcall(function()
			return o:FindFirstChild("Tuner") and o:FindFirstChild("DriveSeat")
		end)
		if ok and o:FindFirstChild("Tuner") and o:FindFirstChild("DriveSeat") then
			table.insert(t, o)
		end
	end
	return t
end
local function getClosestCar(cars)
	local char = LocalPlayer.Character
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return cars[1]
	end
	local best, bestDist = nil, math.huge
	for _, c in ipairs(cars) do
		local seat = c:FindFirstChild("DriveSeat")
		if seat then
			local d = (seat.Position - hrp.Position).Magnitude;
			if d < bestDist then
				bestDist = d;
				best = c
			end
		end
	end
	return best or cars[1]
end
local function getPreferredCar()
	local cars = findAllCars()
	if # cars == 0 then
		return nil
	end
	local want = LocalPlayer.Name .. "sCar"
	local exact = workspace:FindFirstChild(want)
	if exact and exact:FindFirstChild("Tuner") then
		return exact
	end
	local lastName = workspace:GetAttribute("TunerLastCar")
	if lastName then
		local lc = workspace:FindFirstChild(lastName);
		if lc and lc:FindFirstChild("Tuner") then
			return lc
		end
	end
	for _, c in ipairs(cars) do
		if c.Name:lower():find(LocalPlayer.Name:lower(), 1, true) then
			return c
		end
	end
	return getClosestCar(cars)
end
local function getTuner(car)
	if not car then
		return nil
	end
	local m = car:FindFirstChild("Tuner")
	if not m then
		return nil
	end
	local ok, t = pcall(require, m)
	if ok then
		return t
	end
	return nil
end
local currentCar = getPreferredCar()
if not currentCar then
	warn("[Tuner] No vehicle found in workspace");
	return
end
local tuner = getTuner(currentCar)
if not tuner then
	warn("[Tuner] Tuner require failed for " .. currentCar.Name);
	return
end

-- Restore _G tune to current car on open (do not overwrite _G with defaults)
local stored = loadGlobal()
local appliedOnOpen = false
if stored and next(stored) ~= nil then
	local cnt = 0
	for k, v in pairs(stored) do
		if k == "Ratios" and type(v) == "table" and tuner.Ratios then
			for i = 1, 5 do
				if v[i] ~= nil then
					tuner.Ratios[i] = v[i];
					cnt += 1
				end
			end
		elseif tuner[k] ~= nil then
			tuner[k] = v;
			cnt += 1
		end
	end
	if cnt > 0 then
		appliedOnOpen = true;
		print("[Tuner] Restored " .. cnt .. " values from _G to " .. currentCar.Name)
	end
end
local defaults = {}
for k, v in pairs(tuner) do
	if type(v) == "number" or type(v) == "boolean" then
		defaults[k] = v
	end
end
if tuner.Ratios then
	defaults["Ratios"] = {
		tuner.Ratios[1],
		tuner.Ratios[2],
		tuner.Ratios[3],
		tuner.Ratios[4],
		tuner.Ratios[5]
	}
end

