	origLbl.Font = Enum.Font.Gotham;
	origLbl.TextSize = 8;
	origLbl.TextColor3 = Color3.fromRGB(100, 100, 110);
	origLbl.TextXAlignment = Enum.TextXAlignment.Left
	local valLbl = Instance.new("TextLabel", card);
	valLbl.Size = UDim2.fromOffset(68, 20);
	valLbl.Position = UDim2.new(1, - 76, 0, 6);
	valLbl.BackgroundColor3 = Color3.fromRGB(40, 40, 50);
	valLbl.Text = fmt(tuner[key]);
	valLbl.Font = Enum.Font.GothamBold;
	valLbl.TextSize = 11;
	valLbl.TextColor3 = Color3.fromRGB(255, 220, 100);
	Instance.new("UICorner", valLbl).CornerRadius = UDim.new(0, 6)
	local sliderBG = Instance.new("Frame", card);
	sliderBG.Position = UDim2.new(1, - 128, 0, 38);
	sliderBG.Size = UDim2.new(0, 90, 0, 6);
	sliderBG.BackgroundColor3 = Color3.fromRGB(50, 50, 60);
	Instance.new("UICorner", sliderBG).CornerRadius = UDim.new(1, 0)
	local fill = Instance.new("Frame", sliderBG);
	fill.Size = UDim2.new(0.5, 0, 1, 0);
	fill.BackgroundColor3 = Color3.fromRGB(255, 70, 70);
	Instance.new("UICorner", fill).CornerRadius = UDim.new(1, 0)
	local knob = Instance.new("Frame", sliderBG);
	knob.Size = UDim2.fromOffset(12, 12);
	knob.Position = UDim2.new(0.5, - 6, 0.5, - 6);
	knob.BackgroundColor3 = Color3.new(1, 1, 1);
	Instance.new("UICorner", knob).CornerRadius = UDim.new(1, 0);
	knob.ZIndex = 2
	local minusBtn = Instance.new("TextButton", card);
	minusBtn.Size = UDim2.fromOffset(22, 22);
	minusBtn.Position = UDim2.new(1, - 158, 0, 30);
	minusBtn.Text = "−";
	minusBtn.Font = Enum.Font.GothamBold;
	minusBtn.TextSize = 14;
	minusBtn.TextColor3 = Color3.new(1, 1, 1);
	minusBtn.BackgroundColor3 = Color3.fromRGB(50, 50, 60);
	Instance.new("UICorner", minusBtn).CornerRadius = UDim.new(0, 6)
	local plusBtn = Instance.new("TextButton", card);
	plusBtn.Size = UDim2.fromOffset(22, 22);
	plusBtn.Position = UDim2.new(1, - 30, 0, 30);
	plusBtn.Text = "+";
	plusBtn.Font = Enum.Font.GothamBold;
	plusBtn.TextSize = 14;
	plusBtn.TextColor3 = Color3.new(1, 1, 1);
	plusBtn.BackgroundColor3 = Color3.fromRGB(50, 50, 60);
	Instance.new("UICorner", plusBtn).CornerRadius = UDim.new(0, 6)
	local origVal = defaults[key] or tuner[key]
	sliderCards[key] = {
		valLbl = valLbl,
		fill = fill,
		knob = knob,
		origVal = origVal,
		minV = minV,
		maxV = maxV
	}
	local function updateVisual(v)
		local pct = math.clamp((v - minV) / (maxV - minV), 0, 1);
		fill.Size = UDim2.new(pct, 0, 1, 0);
		knob.Position = UDim2.new(pct, - 6, 0.5, - 6);
		valLbl.Text = fmt(v);
		valLbl.TextColor3 = (v ~= origVal and Color3.fromRGB(100, 220, 255) or Color3.fromRGB(255, 220, 100))
	end
	updateVisual(tuner[key])
	local function setVal(newV)
		newV = math.clamp(newV, minV, maxV);
		newV = math.floor(newV / step + 0.5) * step;
		if maxV == 16000 then
			newV = math.floor(newV)
		end
		tuner[key] = newV;
		updateVisual(newV);
		captureLive()
	end
	local dragging = false;
	sliderBG.InputBegan:Connect(function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 then
			dragging = true
		end
	end);
	knob.InputBegan:Connect(function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 then
			dragging = true
		end
	end);
	game:GetService("UserInputService").InputEnded:Connect(function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 then
			dragging = false
		end
	end);
	game:GetService("UserInputService").InputChanged:Connect(function(i)
		if dragging and i.UserInputType == Enum.UserInputType.MouseMovement then
			local rel = (i.Position.X - sliderBG.AbsolutePosition.X) / sliderBG.AbsoluteSize.X;
			setVal(minV + math.clamp(rel, 0, 1) * (maxV - minV))
		end
	end)
	minusBtn.MouseButton1Click:Connect(function()
		setVal(tuner[key] - step)
	end);
	plusBtn.MouseButton1Click:Connect(function()
		setVal(tuner[key] + step)
	end)
	return card
end
local function addToggle(key, displayName, cat, desc, onText, offText)
	onText = onText or "ON";
	offText = offText or "OFF"
	local card = Instance.new("Frame");
	card.Size = UDim2.new(1, - 6, 0, 52);
	card.BackgroundColor3 = Color3.fromRGB(29, 29, 38);
	card.Name = key;
	Instance.new("UICorner", card).CornerRadius = UDim.new(0, 10);
	local s = Instance.new("UIStroke", card);
	s.Color = Color3.fromRGB(44, 44, 54);
