btnApply.MouseButton1Click:Connect(function()
	captureLive()
	local toApply = loadGlobal()
	if not toApply or next(toApply) == nil then
		showToast("No tune to apply", Color3.fromRGB(180, 50, 50), 1);
		return
	end
	local car = currentCar
	if not car or not car.Parent or not car:FindFirstChild("Tuner") then
