			currentCar = car;
			carLabel.Text = "🚗 " .. car.Name
		else
			showToast("No vehicle", Color3.fromRGB(180, 50, 50), 1);
			return
		end
	end
	local targetTuner = getTuner(car)
	if not targetTuner then
		showToast("Cannot access tuner", Color3.fromRGB(180, 50, 50), 1);
		return
	end
	local char = LocalPlayer.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	local wasSeated = hum and hum.SeatPart ~= nil
	local prevSeat = hum and hum.SeatPart
	local targetSeat = car:FindFirstChild("DriveSeat")
	btnApply.Text = "Applying..."
	if wasSeated and hum and hrp then
		hum.Sit = false;
		if prevSeat then
			pcall(function()
				prevSeat.Disabled = true
			end)
		end;
		hum.Jump = true;
		pcall(function()
			hum:ChangeState(Enum.HumanoidStateType.Jumping)
		end)
		local t0 = tick();
		repeat
			task.wait(0.03);
			if hum.SeatPart == nil then
				break
			end;
			hum.Jump = true
		until tick() - t0 > 0.4
		if prevSeat then
			pcall(function()
				prevSeat.Disabled = false
			end)
		end;
		task.wait(0.06)
	end
	local count = 0
	for k, v in pairs(toApply) do
		if k == "Ratios" and type(v) == "table" and targetTuner.Ratios then
			for i = 1, 5 do
				if v[i] ~= nil then
					targetTuner.Ratios[i] = v[i];
					count += 1
				end
			end
		elseif targetTuner[k] ~= nil then
			targetTuner[k] = v;
			count += 1
		end
	end
	tuner = targetTuner
	if wasSeated and hum and targetSeat and hum.Parent then
		if hrp and targetSeat then
			hrp.CFrame = targetSeat.CFrame * CFrame.new(0, 2, 0)
		end;
		task.wait(0.06);
		pcall(function()
			targetSeat:Sit(hum)
		end)
	end
	btnApply.Text = "Apply Tune"
	showToast("Applied " .. count .. " values to " .. car.Name, Color3.fromRGB(0, 170, 90), 1.2)
end)
local lastNotify = 0
workspace.ChildAdded:Connect(function(obj)
	task.wait(0.4)
	if not obj:FindFirstChild("Tuner") or not obj:FindFirstChild("DriveSeat") then
		return
	end
	rebuildDropdown()
	local isMine = obj.Name:lower():find(LocalPlayer.Name:lower(), 1, true) ~= nil
	if not isMine then
		return
	end
	if tick() - lastNotify < 3 then
		return
	end
	lastNotify = tick()
	local s = loadGlobal()
	if s and next(s) ~= nil then
		local t = getTuner(obj)
		if t then
			for k, v in pairs(s) do
				if k == "Ratios" and t.Ratios then
					for i = 1, 5 do
						if v[i] ~= nil then
							t.Ratios[i] = v[i]
						end
					end
				elseif t[k] ~= nil then
					t[k] = v
				end
			end
		end
		if not currentCar or not currentCar.Parent then
			currentCar = obj;
			tuner = t or getTuner(obj);
			carLabel.Text = "🚗 " .. obj.Name .. " ✓ auto-applied";
			carLabel.TextColor3 = Color3.fromRGB(0, 220, 120)
			for key, info in pairs(sliderCards) do
				if tuner[key] ~= nil then
					local v = tuner[key];
					local pct = math.clamp((v - info.minV) / (info.maxV - info.minV), 0, 1);
					info.fill.Size = UDim2.new(pct, 0, 1, 0);
					info.knob.Position = UDim2.new(pct, - 6, 0.5, - 6);
					info.valLbl.Text = fmt(v)
				end
			end
		end
		showToast("New vehicle — tune auto-applied to " .. obj.Name, Color3.fromRGB(0, 170, 90), 2)
	else
		showToast("New vehicle: " .. obj.Name, Color3.fromRGB(70, 90, 220), 1.2)
	end
end)
